sparql_tries.sparql:
SELECT DISTINCT ?year WHERE {
  ?c rc:campaignNumber "26V430000" ;
     rc:affects ?v .
  ?v rc:ofModel ?m ;
     rc:modelYear ?year .
  ?m rc:name "TELLURIDE" ;
     rc:ofMake ?mk .
  ?mk rc:name "KIA" .
}
ORDER BY ?year

SELECT DISTINCT ?componentName WHERE {
  ?c rc:campaignNumber "10V388000" ;
     rc:affectsComponent ?comp .
  ?comp rc:name ?componentName .
}
ORDER BY ?componentName

SELECT DISTINCT ?campaignNumber ?makeName ?date WHERE {
  ?r a rc:RecallCampaign ;
     rc:doNotDrive true ;
     rc:campaignNumber ?campaignNumber ;
     rc:affects ?v .
  ?v rc:ofModel ?m .
  ?m rc:ofMake ?mk .
  ?mk rc:name ?makeName .
  FILTER(UCASE(STR(?makeName)) IN ("HYUNDAI", "KIA", "GENESIS"))
  OPTIONAL { ?r rc:reportReceivedDate ?date }
}
ORDER BY ?date ?campaignNumber

SELECT DISTINCT ?campaignNumber WHERE {
  ?r a rc:RecallCampaign ;
     rc:campaignNumber ?campaignNumber .
  OPTIONAL { ?r rc:initiatedBy ?init }
  OPTIONAL { ?r rc:defectSummary ?d }
  OPTIONAL { ?r rc:correctiveSummary ?c }
  OPTIONAL { ?r rc:consequenceSummary ?q }
  FILTER(
    (BOUND(?init) && (UCASE(STR(?init)) = "OVSC" || CONTAINS(UCASE(STR(?init)), "OVSC") || CONTAINS(UCASE(STR(?init)), "VEHICLE SAFETY COMPLIANCE"))) ||
    (BOUND(?d) && (CONTAINS(STR(?d), "OVSC") || CONTAINS(UCASE(STR(?d)), "OFFICE OF VEHICLE SAFETY COMPLIANCE"))) ||
    (BOUND(?c) && (CONTAINS(STR(?c), "OVSC") || CONTAINS(UCASE(STR(?c)), "OFFICE OF VEHICLE SAFETY COMPLIANCE"))) ||
    (BOUND(?q) && (CONTAINS(STR(?q), "OVSC") || CONTAINS(UCASE(STR(?q)), "OFFICE OF VEHICLE SAFETY COMPLIANCE")))
  )
}
ORDER BY ?campaignNumber

SELECT DISTINCT ?campaignNumber ?date WHERE {
  ?c a rc:RecallCampaign ;
     rc:campaignNumber ?campaignNumber ;
     rc:reportReceivedDate ?date ;
     rc:affects ?v .
  ?v rc:ofModel ?m .
  ?m rc:name "PALISADE" ;
     rc:ofMake ?mk .
  ?mk rc:name "HYUNDAI" .
  FILTER(?date >= "2024-01-01"^^xsd:date && ?date <= "2024-12-31"^^xsd:date)
}
ORDER BY ?date ?campaignNumber

SELECT DISTINCT ?makeName ?modelName WHERE {
  ?target rc:name "SERVICE BRAKES, HYDRAULIC:ANTILOCK/TRACTION CONTROL/ELECTRONIC LIMITED SLIP:CONTROL UNIT/MODULE" .
  ?comp skos:broader* ?target .
  ?c rc:affectsComponent ?comp ;
     rc:affects ?v .
  ?v rc:ofModel ?model .
  ?model rc:name ?modelName ;
         rc:ofMake ?make .
  ?make rc:name ?makeName .
}
ORDER BY ?makeName ?modelName

SELECT ?componentName (COUNT(DISTINCT ?c) AS ?campaignCount) WHERE {
  ?c rc:affectsComponent ?comp .
  ?comp rc:name ?componentName .
  FILTER EXISTS { ?comp skos:broader ?parent }
  FILTER EXISTS {
    ?c1 rc:affectsComponent ?comp ; rc:affects ?v1 .
    ?v1 rc:ofModel ?m1 . ?m1 rc:ofMake ?mk1 . ?mk1 rc:name "HYUNDAI" .
  }
  FILTER EXISTS {
    ?c2 rc:affectsComponent ?comp ; rc:affects ?v2 .
    ?v2 rc:ofModel ?m2 . ?m2 rc:ofMake ?mk2 . ?mk2 rc:name "KIA" .
  }
}
GROUP BY ?componentName
ORDER BY DESC(?campaignCount) ?componentName
LIMIT 10

SELECT ?campaignNumber (COUNT(DISTINCT ?make) AS ?makeCount) (GROUP_CONCAT(DISTINCT ?makeName; separator=", ") AS ?makes)
WHERE {
  ?c a rc:RecallCampaign ;
     rc:campaignNumber ?campaignNumber ;
     rc:affects ?v .
  ?v rc:ofModel ?m .
  ?m rc:ofMake ?make .
  ?make rc:name ?makeName .
}
GROUP BY ?campaignNumber
HAVING (COUNT(DISTINCT ?make) > 1)
ORDER BY DESC(?makeCount) ?campaignNumber

SELECT DISTINCT ?campaignNumber WHERE {
  ?make rc:name ?makeName .
  FILTER(UCASE(STR(?makeName)) = "HYUNDAI")
  ?model rc:ofMake ?make ;
         rc:name ?modelName .
  FILTER(UCASE(STR(?modelName)) = "SANTA FE")
  ?variant rc:ofModel ?model ;
           rc:modelYear ?year .
  FILTER(STR(?year) = "2021")
  ?campaign rc:affects ?variant ;
            rc:campaignNumber ?campaignNumber .
}
ORDER BY ?campaignNumber

SELECT ?model ?makeName ?modelName (COUNT(DISTINCT ?campaign) AS ?campaignCount)
WHERE {
  ?campaign a rc:RecallCampaign ;
            rc:affects ?variant .
  ?variant rc:ofModel ?model .
  ?model rc:name ?modelName .
  OPTIONAL { ?model rc:ofMake ?make . ?make rc:name ?makeName . }
}
GROUP BY ?model ?makeName ?modelName
ORDER BY DESC(?campaignCount) ?modelName

SELECT (COUNT(DISTINCT ?c) AS ?count) WHERE {
  ?c a rc:RecallCampaign ;
     rc:reportReceivedDate ?d ;
     rc:affects ?v .
  ?v rc:ofModel ?m .
  ?m rc:ofMake ?mk .
  ?mk rc:name ?mkName .
  FILTER(UCASE(STR(?mkName)) IN ("HYUNDAI", "KIA", "GENESIS"))
  FILTER(YEAR(?d) = 2023)
}

SELECT ?topName (COUNT(DISTINCT ?model) AS ?modelCount) WHERE {
  ?campaign rc:affectsComponent ?comp ;
            rc:affects ?variant .
  ?variant rc:ofModel ?model .
  ?comp skos:broader* ?top .
  FILTER NOT EXISTS { ?top skos:broader ?parent }
  ?top rc:name ?topName .
}
GROUP BY ?topName
ORDER BY DESC(?modelCount)

SELECT ?campaignNumber ?affected WHERE {
  ?c a rc:RecallCampaign ;
     rc:parkOutside true ;
     rc:campaignNumber ?campaignNumber ;
     rc:potentiallyAffected ?affected .
}
ORDER BY DESC(?affected)
LIMIT 1

SELECT (COUNT(DISTINCT ?c) AS ?count) WHERE {
  ?c a rc:RecallCampaign ;
     rc:initiatedBy ?by .
  FILTER(CONTAINS(UCASE(STR(?by)), "ODI"))
}

SELECT ?topName (COUNT(DISTINCT ?c) AS ?n) WHERE {
  ?c a rc:RecallCampaign ;
     rc:affects ?v ;
     rc:affectsComponent ?comp .
  ?v rc:ofModel ?m .
  ?m rc:ofMake ?mk .
  ?mk rc:name ?mkName .
  FILTER(UCASE(STR(?mkName)) = "GENESIS")
  ?comp skos:broader* ?top .
  FILTER NOT EXISTS { ?top skos:broader ?any }
  ?top rc:name ?topName .
}
GROUP BY ?topName
ORDER BY DESC(?n) ?topName

SELECT (COUNT(DISTINCT ?year) AS ?count) WHERE {
  ?c a rc:RecallCampaign ; rc:affects ?v .
  ?v rc:ofModel ?m ; rc:modelYear ?year .
  ?m rc:name "SONATA" ; rc:ofMake ?mk .
  ?mk rc:name "HYUNDAI" .
}

SELECT ?year (COUNT(DISTINCT ?c) AS ?n) WHERE {
  ?c a rc:RecallCampaign ;
     rc:reportReceivedDate ?d ;
     rc:affects ?v .
  ?v rc:ofModel ?m .
  ?m rc:ofMake ?mk .
  ?mk rc:name ?mkName .
  FILTER(UCASE(STR(?mkName)) IN ("HYUNDAI", "KIA", "GENESIS"))
  BIND(YEAR(?d) AS ?year)
}
GROUP BY ?year
ORDER BY DESC(?n) ?year

SELECT DISTINCT ?campaignNumber ?date WHERE {
  ?r a rc:RecallCampaign ;
     rc:campaignNumber ?campaignNumber .
  OPTIONAL { ?r rc:reportReceivedDate ?date }
  OPTIONAL { ?r rc:defectSummary ?d }
  OPTIONAL { ?r rc:consequenceSummary ?c }
  OPTIONAL { ?r rc:affectsComponent/rc:name ?comp }
  FILTER(
    REGEX(COALESCE(?d, ""), "hydrogen", "i") ||
    REGEX(COALESCE(?c, ""), "hydrogen", "i") ||
    REGEX(COALESCE(?comp, ""), "HYDROGEN", "i")
  )
}
ORDER BY ?date ?campaignNumber

SELECT DISTINCT ?campaignNumber WHERE {
  ?r a rc:RecallCampaign ;
     rc:campaignNumber ?campaignNumber .
  OPTIONAL { ?r rc:defectSummary ?d }
  OPTIONAL { ?r rc:correctiveSummary ?c }
  OPTIONAL { ?r rc:affectsComponent ?comp . ?comp rc:name ?compName }
  FILTER(
    REGEX(COALESCE(?d, ""), "ICCU|integrated charging control unit", "i") ||
    REGEX(COALESCE(?c, ""), "ICCU|integrated charging control unit", "i") ||
    REGEX(COALESCE(?compName, ""), "ICCU|INTEGRATED CHARGING CONTROL", "i")
  )
}
ORDER BY ?campaignNumber

SELECT DISTINCT ?campaignNumber ?defect WHERE {
  ?r a rc:RecallCampaign ;
     rc:campaignNumber ?campaignNumber .
  OPTIONAL { ?r rc:defectSummary ?d }
  OPTIONAL { ?r rc:rootCause ?rc0 }
  OPTIONAL { ?r rc:consequenceSummary ?cs }
  BIND(CONCAT(COALESCE(?d, ""), " ", COALESCE(?rc0, ""), " ", COALESCE(?cs, "")) AS ?txt)
  BIND(COALESCE(?d, "") AS ?defect)
  FILTER(REGEX(?txt, "water|moisture|fluid|liquid", "i"))
  FILTER(REGEX(?txt, "trailer|tow", "i"))
  FILTER(REGEX(?txt, "module", "i"))
}
ORDER BY ?campaignNumber

SELECT DISTINCT ?campaignNumber ?defect WHERE {
  ?r a rc:RecallCampaign ;
     rc:campaignNumber ?campaignNumber ;
     rc:defectSummary ?defect .
  FILTER(REGEX(?defect, "connecting rod", "i") && REGEX(?defect, "bearing", "i") && REGEX(?defect, "wear", "i"))
}
ORDER BY ?campaignNumber
